export default function prepare({ documentId, text, runId, qdrantUrl, collection }) {
  if (
    !documentId ||
    !text?.trim() ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(runId) ||
    !/^https:\/\//.test(qdrantUrl) ||
    !collection ||
    collection.includes("YOUR_")
  )
    throw Error("Configure document, unique UUID run ID and Qdrant");
  const chunks = [];
  for (let i = 0; i < text.length; i += 1400) {
    chunks.push(text.slice(i, i + 1600));
    if (chunks.length > 300) throw Error("Document exceeds supported size");
  }
  return {
    chunks,
    request: { model: "text-embedding-3-small", input: chunks, dimensions: 1536 },
    url:
      qdrantUrl.replace(/\/$/, "") +
      "/collections/" +
      encodeURIComponent(collection) +
      "/points?wait=true",
  };
}

