export default async function plan(
  { response, chunks, documentId, runId, url, acknowledge, resolution },
  ctx,
) {
  const data = response?.data;
  if (!Array.isArray(data) || data.length !== chunks.length)
    throw Error("Invalid embedding response");
  const base = runId.toLowerCase().replaceAll("-", "").slice(0, 24),
    points = chunks.map((text, i) => {
      const vector = data.find((x) => x.index === i)?.embedding;
      if (
        !Array.isArray(vector) ||
        vector.length !== 1536 ||
        vector.some((n) => !Number.isFinite(n))
      )
        throw Error("Invalid vector");
      const h = base + i.toString(16).padStart(8, "0"),
        id = `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
      return { id, vector, payload: { runId, documentId, text } };
    });
  const key = "exam-index:" + runId;
  let s = await ctx.state.get(key);
  const signature = JSON.stringify(chunks);
  if (s && (s.documentId !== documentId || s.signature !== signature))
    throw Error("Run ID reused for a different document");
  if (s?.status === "done") return { write: false, key, url, request: { points: [] } };
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect indexed points before retrying " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done", documentId, signature });
      return { write: false, key, url, request: { points: [] } };
    }
  }
  await ctx.state.set(key, { status: "pending", documentId, signature });
  return { write: true, key, url, request: { points } };
}

