export default async function confirm({ key, documentId, statusCode, body }, ctx) {
  if (statusCode !== 200 || body?.status !== "ok" || body?.result?.status !== "completed")
    throw Error("Unknown Qdrant indexing result");
  const s = await ctx.state.get(key);
  if (s?.status !== "pending" || s.documentId !== documentId)
    throw Error("Missing index reservation");
  await ctx.state.set(key, { status: "done", documentId, signature: s.signature });
  return { ok: true };
}

