export default async function next(
  { runId, questions, spreadsheetId, openRange, closedRange, acknowledge, resolution },
  ctx,
) {
  if (!spreadsheetId || !openRange || !closedRange || spreadsheetId.includes("YOUR_"))
    throw Error("Configure spreadsheet");
  const key = "exam-rows:" + runId;
  let s = await ctx.state.get(key);
  if (!s) {
    const open = questions?.open,
      closed = questions?.closed;
    if (
      !Array.isArray(open) ||
      open.length !== 10 ||
      !Array.isArray(closed) ||
      closed.length !== 10 ||
      [...open, ...closed].some((q) => typeof q !== "string" || !q.trim())
    )
      throw Error("Expected ten questions of each type");
    s = {
      items: [
        ...open.map((question) => ({ kind: "open", question })),
        ...closed.map((question) => ({ kind: "closed", question })),
      ],
      index: 0,
      pending: null,
      spreadsheetId,
    };
    await ctx.state.set(key, s);
  }
  if (s.spreadsheetId !== spreadsheetId) throw Error("Run ID reused");
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect spreadsheet row before retrying " + s.pending);
    if (resolution === "confirmed") s.index++;
    s.pending = null;
    await ctx.state.set(key, s);
  }
  let item = s.items[s.index];
  return {
    key,
    has: !!item,
    question: item?.question || "",
    kind: item?.kind || "open",
    index: s.index,
    spreadsheetId,
    range: item?.kind === "closed" ? closedRange : openRange,
    request: { model: "text-embedding-3-small", input: item?.question || "done", dimensions: 1536 },
  };
}

