export default function query({ response, runId, qdrantUrl, collection }) {
  const vector = response?.data?.[0]?.embedding;
  if (!Array.isArray(vector) || vector.length !== 1536) throw Error("Invalid query embedding");
  return {
    url:
      qdrantUrl.replace(/\/$/, "") +
      "/collections/" +
      encodeURIComponent(collection) +
      "/points/query",
    request: {
      query: vector,
      filter: { must: [{ key: "runId", match: { value: runId } }] },
      with_payload: true,
      limit: 4,
    },
  };
}

