export default function context({ body }) {
  const points = body?.result?.points;
  if (body?.status !== "ok" || !Array.isArray(points) || !points.length)
    throw Error("No retrieved context");
  const text = points
    .map((x) => x.payload?.text)
    .filter((x) => typeof x === "string" && x.trim())
    .join("\n\n");
  if (!text) throw Error("No text in retrieved context");
  return { text };
}

