export default async function reserve({ key, index, kind, question, answer }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.index !== index || s.pending) throw Error("Invalid row state");
  if (typeof answer?.answer !== "string" || !answer.answer.trim()) throw Error("Missing answer");
  let row;
  if (kind === "open") row = [question, answer.answer];
  else {
    if (
      !Array.isArray(answer.options) ||
      answer.options.length !== 4 ||
      answer.options.some((x) => typeof x !== "string" || !x.trim()) ||
      !answer.options.includes(answer.answer)
    )
      throw Error("Invalid four-option answer");
    row = [question, ...answer.options, answer.answer];
  }
  s.pending = key + ":" + index;
  await ctx.state.set(key, s);
  return { values: [row] };
}

