export default async function confirm(
  { key, index, updatedRows, spreadsheetId, actualSpreadsheetId },
  ctx,
) {
  if (updatedRows !== 1 || spreadsheetId !== actualSpreadsheetId)
    throw Error("Unknown spreadsheet append");
  const s = await ctx.state.get(key);
  if (!s || s.index !== index || s.pending !== key + ":" + index)
    throw Error("Missing row reservation");
  s.pending = null;
  s.index++;
  await ctx.state.set(key, s);
  return { ok: true };
}
